}

function kazanan(tahta) {
  const yonler = [
    [0, 1],
    [1, 0],
    [1, 1],
    [1, -1]
  ];
  for (let row = 0; row < 6; row++) {
    for (let col = 0; col < 7; col++) {
      const idx = row * 7 + col;
      const isaret = tahta[idx];
      if (isaret === null) continue;
      for (const [dr, dc] of yonler) {
        let tamam = true;
