        ctx.arc(cx, cy, HUCRE / 2 - 8, 0, Math.PI * 2);
        const isaret = tahta[idx];
        ctx.fillStyle = isaret ? renkler[isaret] : '#0b1440';
        ctx.fill();
        ctx.strokeStyle = '#000';
